ALTER TABLE "approval_requests" DROP CONSTRAINT "approval_requests_decision_check";--> statement-breakpoint
ALTER TABLE "approval_requests" ADD CONSTRAINT "approval_requests_decision_check" CHECK (("approval_requests"."status"='pending' AND "approval_requests"."decided_at" IS NULL AND "approval_requests"."recorded_by" IS NULL) OR ("approval_requests"."status" IN ('approved','changes_requested','cancelled') AND "approval_requests"."decided_at" IS NOT NULL AND "approval_requests"."recorded_by" IS NOT NULL AND ("approval_requests"."status"='approved' OR ("approval_requests"."feedback" IS NOT NULL AND length(trim("approval_requests"."feedback"))>0))));